  seq(t, nodes, parentId) {
    let prev = null, first = null;
    for (const node of nodes || []) {
      if (!node) continue;
      const id = this.block(t, node, prev || parentId);
      if (prev) t.blocks[prev].next = id;
      else first = id;
      prev = id;
    }
