  K.build(em, project);

  // ---- write ----
  const out = entries.map((e) => e.name === 'project.json'
    ? { name: e.name, data: Buffer.from(JSON.stringify(project), 'utf8') }
    : e);
  zipWrite(out, OUT);
  fs.writeFileSync(OUT_JSON, JSON.stringify(project));

