const kernelIndex = `'use strict';
/**
 * v5 kernel assembly.  Every procedure emitted here is a LEAF: it never calls
 * another custom block.  Only the RUN / flag hats call procedures.
 */
const { E, S } = require('../dsl.js');

// ---- Interpreter-private storage (all state lives in lists) ----
const LISTS = [
  // code image
  'Iop', 'Ia', 'Ib', 'Iline', 'Kval',
  // runtime stacks
  'Stk', 'FrKind', 'FrRet', 'FrEnv', 'FrBase', 'FrTop',
  // binding chains / maps
  'BindName', 'BindVal', 'BindNext', 'MapHead', 'MapParent', 'MapKind',
  // symbol tables
  'FnKind', 'FnName', 'FnArity', 'FnParam', 'FnBody', 'FnEnv', 'FnFlags',
  'ClName', 'ClBase', 'ClMap', 'InClass', 'InMap',
  // heap
  'LStart', 'LCount', 'LCap', 'LArr',
  // lexer / parser / compiler working space
  'TokT', 'TokV', 'TokL', 'IndStk',
  'NdK', 'NdA', 'NdS', 'NdN', 'NdC',
  'PTgt', 'PSite',
];
const VARS = ['pc', 'sp', 'frTop', 'tk', 'ip', 'err', 'ti', 'tmp', 'tmp2', 'a0', 'a1', 'a2', 'a3'];

function build(em, project) {
  // declare storage
  for (const n of VARS) em.addVar('Interpreter', n, 0);
  for (const n of LISTS) em.addList('Interpreter', n, []);

  // ---------------- hats ----------------
  em.hat('Interpreter', 'event_whenflagclicked', {}, [
    S.raw('looks_hide'),
    S.call('reset_vm', []),
  ]);

  em.hat('Interpreter', 'event_whenbroadcastreceived', { BROADCAST_OPTION: 'HALT' }, [
    S.raw('control_stop', [], { STOP_OPTION: 'other scripts in sprite' }),
    em.varSet('Stage', 'running', E.num(0)),
    S.set('busy', E.num(0)),
    S.set('dirty', E.num(1)),
  ]);

  em.hat('Interpreter', 'event_whenbroadcastreceived', { BROADCAST_OPTION: 'RUN' }, [
    S.set('error', E.str('')),
    S.set('status', E.str('Running')),
    S.set('steps', E.num(0)),
    S.set('pc', E.num(0)),
    S.ldelall('Output'), S.ldelall('Names'), S.ldelall('Values'), S.ldelall('Types'),
    S.set('outpage', E.num(1)),
    S.set('varpage', E.num(1)),
    S.call('reset_vm', []),
    S.call('print_line', [E.str('MiniPy v5 kernel online')]),
    S.set('running', E.num(0)),
    S.set('busy', E.num(0)),
    S.set('dirty', E.num(1)),
  ]);

  // ---------------- leaf procedures ----------------
  em.defineProc('Interpreter', 'reset_vm', [], [
    S.set('pc', E.num(0)), S.set('sp', E.num(0)), S.set('frTop', E.num(0)), S.set('tk', E.num(0)),
    S.set('err', E.str('')),
    ...LISTS.map((n) => S.ldelall(n)),
  ], true);

  em.defineProc('Interpreter', 'print_line', ['msg'], K_print(em), true);
}

function K_print(em) {
  // wraps the message into 30-column console lines (same policy as v4 log)
  return [
    S.set('tmp', E.str('')),
    S.set('ti', E.num(1)),
    S.Repeat(E.slen(em.arg('msg')), [
      S.set('tmp', E.join(E.var('tmp'), E.letter(E.var('ti'), em.arg('msg')))),
      S.If(E.eq(E.slen(E.var('tmp')), E.num(30)), [
        S.ladd('Output', E.var('tmp')),
        S.set('tmp', E.str('')),
      ]),
      S.chg('ti', E.num(1)),
    ]),
    S.If(E.or(E.not(E.eq(E.var('tmp'), E.str(''))), E.eq(E.slen(em.arg('msg')), E.num(0))), [
      S.ladd('Output', E.var('tmp')),
    ]),
    S.While(E.gt(E.len('Output'), E.num(300)), [S.ldel('Output', E.num(1))]),
    S.set('outpage', E.num(1)),
    S.set('dirty', E.num(1)),
  ];
}

module.exports = { build, LISTS, VARS };
`;
await tools.write({ file_path: "D:\\编程\\scratch\\ai\\minipython\\_work\\v5\\kernel\\index.js", content: kernelIndex });
console.log("written build5.js + kernel/index.js");
", "description": "Write build5.js and S1 kernel skeleton"}

