                  S.set('t5', V()),
                  S.If(E.eq(E.var('t5'), E.str('-')), [...P.pushO('neg'), tp1()], [
                    S.If(E.eq(E.var('t5'), E.str('+')), [...P.pushO('pos'), tp1()], [
                      S.If(E.eq(E.var('t5'), E.str('~')), [...P.pushO('inv'), tp1()], [
