        S.If(E.eq(T(), E.str('S')), [
          ...A.nodeN('t3', E.str('lit'), E.join(E.str('S'), V()), []), ...P.pushV(E.var('t3'), E.str('')), tp1(), S.set('want', E.num(1)),
