  for (let i = 0; i < 5; i++) runtime._step();
  setList(stage, 'Code', process.argv[3].split('|'));
  for (const n of ['mode','ticket','stopreq','running']) { const v = sv(stage, n); if (v) v.value = 0; }
  sv(stage,'ticket').value = 1; sv(stage,'running').value = 1; sv(stage,'speed').value = 1;
  runtime.startHats('event_whenbroadcastreceived', { BROADCAST_OPTION: 'RUN' });
  for (let i = 0; i < 4; i++) runtime._step();
  for (const n of ['TokT','TokV','NdK','NdA','NdS','NdN','NdC','Pv','Po','PcT','PcB','SuN','LArr','LStart','LCount']) {
    const l = sl(interp, n);
    realLog(n + ' len=' + (l ? l.value.length : 'MISSING') + '  ' + JSON.stringify(l ? l.value.slice(0,10) : null));
  }
  for (const n of ['nTop','tp','pvSp','poSp','pcSp','suSp','blSp','ps','stK','err','rootNd','noneNd','hTop','sctx','pgi']) {
    const v = sv(interp, n);
    realLog(n + ' = ' + JSON.stringify(v ? v.value : 'MISSING'));
  }
  realLog('Output = ' + JSON.stringify(sl(stage,'Output').value));
  process.exit(0);
})().catch((e) => realLog('ERR', e && e.stack || e));
`;
await tools.write({ file_path: "D:\\编程\\scratch\\ai\\minipython\\_work\\v5\\probe.cjs", content: probe });
const r = await tools.pwsh({ command: "node _work\\v5\\probe.cjs MiniPy_v5.sb3 '#!dump|x = 1 + 2' 1> _work\\v5\\p.txt 2> $null; Get-Content _work\\v5\\p.txt -Raw", description: "Inspect parser state", workdir: "D:\\编程\\scratch\\ai\\minipython", timeoutMs: 120000 });
