      S.If(E.eq(E.var('dop'), E.str('LAMBDA')), [], [...pushT('e', E.str('STOREV'), E.var('dsp'))]),
      S.If(E.eq(E.var('dop'), E.str('DEF')), [...pushT('e', E.str('STOREV'), E.var('dsp'))]),
      ...pushT('d', E.var('dop'), E.join(E.var('t7'), E.join(E.str('|'), E.var('lbody')))),
