    return [
      S.set('hl', E.add(E.var('labTop'), E.num(100 + i))),
      S.chg('labTop', E.num(0)),
      // DUP; type; ISINST; JZ lnext; bind; body; JMP lend; lnext
      ...pushT('l', E.var('hl')),
      ...pushT('j', E.str('JMP'), E.var('lend')),
      ...pushT('n', Ch(nd(), E.num(2 + i * 2))),
