      S.If(E.eq(ck(), E.str('sub')), [...pushT('e', E.str('SUBS'), NdA(nd())), ...kidsRev(0)]),
      S.If(E.eq(ck(), E.str('list')), [...pushT('e', E.str('BUILD'), E.str('L')), ...kidsRev(0)]),
      S.If(E.eq(ck(), E.str('tuple')), [...pushT('e', E.str('BUILD'), E.str('T')), ...kidsRev(0)]),
