      S.If(E.not(E.eq(v, E.num(0))), [S.set(dst, E.num(1))]),
    ], [
      S.If(E.eq(E.letter(E.num(1), v), E.str('S')), [
        S.If(E.gt(E.slen(v), E.num(1)), [S.set(dst, E.num(1))]),
