        S.If(E.eq(op(), E.str('>')), [S.If(E.gt(E.var('cmp'), E.num(0)), [S.set('res', E.str('B1'))])]),
        S.If(E.eq(op(), E.str('<=')), [S.If(E.le(E.var('cmp'), E.num(0)), [S.set('res', E.str('B1'))])]),
