  // ================= opcode handlers =================
  function arithBlock() {
    const op = () => E.var('op');
    return [
      S.If(E.eq(op(), E.str('+')), [S.set('res', E.add(E.var('na'), E.var('nb')))]),
      S.If(E.eq(op(), E.str('-')), [S.set('res', E.sub(E.var('na'), E.var('nb')))]),
      S.If(E.eq(op(), E.str('*')), [S.set('res', E.mul(E.var('na'), E.var('nb')))]),
      S.If(E.eq(op(), E.str('/')), [S.set('res', E.div(E.var('na'), E.var('nb')))]),
