  function binBlock() {
    const ia = () => E.item('Ia', E.var('pc'));
    return [
      ...vpop('vb'), ...vpop('va'),
      S.set('op', ia()),
      ...L.payInto(E.var('va'), 'na'),
      ...L.payInto(E.var('vb'), 'nb'),
      S.set('res', E.str('')), S.set('rt', E.str('N')),
      S.If(E.eq(E.var('op'), E.str('and')), [
        ...truthOf(E.var('va'), 'tb'),
        S.If(E.eq(E.var('tb'), E.num(0)), [S.set('res', E.var('va'))], [S.set('res', E.var('vb'))]),
        S.set('rt', E.str('R')),
      ]),
