          S.chg('i', E.num(1)),
        ]),
        S.set('res2', E.join(E.str(''), E.var('pos'))),
        S.If(E.eq(E.var('mname'), E.str('count|00000')), [S.set('res2', E.join(E.str(''), E.var('cnt')))]),
