    const ia = () => E.item('Ia', E.var('pc'));
    const is = (o, body) => S.If(E.eq(op(), E.str(o)), body);
    return [
      is('HALT', [S.set('halted', E.num(1))]),
      is('NOP', []),
      is('PUSHK', [...vpush(E.item('Kval', ia()))]),
      is('PUSHN', [...vpush(ia())]),
      is('PUSHV', [
        ...lookup(ia()),
        S.If(E.eq(E.var('lkF'), E.num(1)), [...vpush(E.var('lkV'))], [
          ...L.failAt(E.join(E.str('NameError: '), E.join(E.var('lkN'), E.str(' is not defined'))), E.var('pc')),
        ]),
      ]),
      is('POP', [S.chg('sp', E.num(-1))]),
      is('DUP', [S.set('vd', E.item('Stk', E.var('sp'))), ...vpush(E.var('vd'))]),
      is('STOREV', [
        ...vpop('vb'),
        S.If(E.eq(E.var('frTop'), E.num(1)), [
