    S.set('bTop', E.num(0)), S.set('fTop', E.num(0)), S.set('cTop', E.num(0)), S.set('iTop', E.num(0)),
    S.set('sp', E.num(0)), S.set('frTop', E.num(0)), S.set('hdTop', E.num(0)), S.set('ticks', E.num(0)),
