  ];
  // ---------------- heap ----------------
  const heapNew = (dst) => [
    S.chg('hTop', E.num(1)), S.set(dst, E.var('hTop')),
    ...L.setAt('LStart', E.var(dst), E.add(E.len('LArr'), E.num(1))),
    ...L.setAt('LCount', E.var(dst), E.num(0)),
