      S.If(E.lt(E.var('ncap'), E.num(4)), [S.set('ncap', E.num(4))]),
      S.Until(E.ge(E.var('ncap'), nExpr), [S.set('ncap', E.mul(E.var('ncap'), E.num(2)))]),
      S.set('nst', E.add(E.len('LArr'), E.num(1))),
