      S.If(E.eq(E.var('ttg'), E.str('S')), [...L.payInto(E.var('tsv'), 'tsp'), S.set(dst, E.var('tsp'))]),
      S.If(E.eq(E.var('ttg'), E.str('B')), [
        S.set(dst, E.str('False')),
        S.If(E.eq(E.letter(E.num(2), E.var('tsv')), E.str('1')), [S.set(dst, E.str('True'))]),
