      ]),
    ];
  }
  function repeatBlock() {
    return [
      S.If(E.and(E.eq(E.letter(E.num(1), E.var('va')), E.str('S')), L.isNum(E.var('vb'))), [
        S.set('res', E.str('S')), S.set('na', E.var('nb')), S.set('nb', E.var('va')),
        S.Repeat(E.var('nb'), [S.set('res', E.join(E.var('res'), E.var('na')))]),
        S.set('rt', E.str('R')),
