      ]),
      S.If(E.or(E.eq(E.var('op'), E.str('in')), E.eq(E.var('op'), E.str('notin'))), [inBlock()]),
      S.If(E.or(E.eq(E.var('op'), E.str('==')), E.eq(E.var('op'), E.str('!='))), [
        S.set('res', E.str('B0')), S.set('rt', E.str('R')),
        S.If(E.and(L.isNum(E.var('va')), L.isNum(E.var('vb'))), [
