      is('UN', [unBlock()]),
      is('CMP', [cmpBlock()]),
      is('BUILD', [buildBlock()]),
      is('SUBS', [subsBlock()]),
      is('SUBSSET', [subsSetBlock()]),
      is('GETATTR', [getattrBlock()]),
      is('SETATTR', [setattrBlock()]),
      is('ITER', [iterBlock()]),
      is('NEXT', [nextBlock()]),
      is('CALL', [callBlock()]),
      is('METH', [methBlock()]),
      is('DEF', [defBlock()]),
      is('LAMBDA', [defBlock()]),
      is('CLASS', [classBlock()]),
      is('RET', [retBlock()]),
      is('RETN', [retnBlock()]),
      is('ASRT', [asrtBlock()]),
