      S.If(E.eq(E.var('t1g'), E.str('Z')), [S.set(dst, E.str('None'))]),
      S.If(E.eq(E.var('t1g'), E.str('L')), [S.set(dst, E.str('[...]'))]),
      S.If(E.eq(E.var('t1g'), E.str('T')), [S.set(dst, E.str('(...)'))]),
      S.If(E.eq(E.var('t1g'), E.str('D')), [S.set(dst, E.str('{...}'))]),
