        S.set('i', E.num(1)),
        S.Repeat(E.item('LCount', E.var('tso')), [
          S.If(E.gt(E.var('i'), E.num(1)), [S.set(dst, E.join(E.var(dst), E.str(', ')))]),
          ...tostr1(heapGet(E.var('tso'), E.var('i')), 'tsx'),
          S.set(dst, E.join(E.var(dst), E.var('tsx'))),
