      ]),
      S.If(E.eq(op(), E.str('%')), [
        S.If(E.eq(E.var('nb'), E.num(0)), [...L.failAt(E.str('ZeroDivisionError: modulo by zero'), E.var('pc'))], [
          S.set('res', E.sub(E.var('na'), E.mul(E.var('nb'), E.math('floor', E.div(E.var('na'), E.var('nb')))))),
