    }
    tgt.variables = kept;
  }
  return {
    before: Object.keys(varsDict).length,
    after: Object.keys(newVars).length,
    units: units.length,
    splitVars,
    pooledUnits, pinnedUnits, rewrites,
  };
}
module.exports = { optimize };
`;
