        S.Repeat(E.slen(E.var('na')), [
          S.set('cch', E.letter(E.var('i'), E.var('na'))),
          S.If(E.eq(E.var('cch'), E.str('{')), [
            S.set('skp', E.num(1)),
            ...tostr(E.item('Stk', E.add(E.var('ubase'), E.var('ai2'))), 'ex2'),
            S.set('out', E.join(E.var('out'), E.var('ex2'))),
            S.set('ai2', E.add(E.var('ai2'), E.num(1))),
          ], [
            S.If(E.eq(E.var('cch'), E.str('}')), [S.set('skp', E.num(0))], [
              S.If(E.eq(E.var('skp'), E.num(0)), [S.set('out', E.join(E.var('out'), E.var('cch')))]),
            ]),
          ]),
          S.chg('i', E.num(1)),
        ]),";
const B="        S.set('out', E.str('')), S.set('i', E.num(1)), S.set('ai2', E.num(2)), S.set('skp', E.num(0)),
        S.set('farg', E.num(0)), S.set('fdig', E.str('')),
        S.Repeat(E.slen(E.var('na')), [
          S.set('cch', E.letter(E.var('i'), E.var('na'))),
          S.If(E.eq(E.var('cch'), E.str('{')), [
            S.set('skp', E.num(1)), S.set('fdig', E.str('')),
          ], [
            S.If(E.eq(E.var('cch'), E.str('}')), [
              S.set('skp', E.num(0)), S.set('farg', E.var('ai2')),
              S.If(E.gt(E.slen(E.var('fdig')), E.num(0)), [
                S.set('farg', E.add(E.num(2), E.var('fdig'))),
              ]),
              ...tostr(E.item('Stk', E.add(E.var('ubase'), E.var('farg'))), 'ex2'),
              S.set('out', E.join(E.var('out'), E.var('ex2'))),
              S.set('ai2', E.add(E.var('ai2'), E.num(1))),
            ], [
              S.If(E.eq(E.var('skp'), E.num(1)), [
                S.set('fdig', E.join(E.var('fdig'), E.var('cch'))),
              ], [
                S.set('out', E.join(E.var('out'), E.var('cch'))),
              ]),
            ]),
          ]),
          S.chg('i', E.num(1)),
        ]),";
if(c.indexOf(A)>=0){ c=c.replace(A,B); console.log('format indexed ok'); } else { const a2=A.split(NL).join(String.fromCharCode(13)+NL); if(c.indexOf(a2)>=0){ c=c.replace(a2,B.split(NL).join(String.fromCharCode(13)+NL)); console.log('ok crlf'); } else console.log('MISS'); }
fs.writeFileSync(P,c);

