const fs = require('fs'), path = require('path');
const AdmZip = null;
const zlib = require('zlib');
// use the same loader as run5.cjs: read the sb3 through scratch-vm's parser
const { execSync } = require('child_process');
const proj = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const byId = {}; for (const id in proj.blocks) byId[id] = proj.blocks[id];
const targets = proj.targets.filter(t => t.name === 'Interpreter');
const refs = {};
function walk(id, top) {
  const b = byId[id]; if (!b) return;
  if (b.fields && b.fields.VARIABLE) { const n = b.fields.VARIABLE[0]; (refs[n] = refs[n] || new Set()).add(top); }
  for (const k in b.inputs) { const inp = b.inputs[k]; for (let i = 1; i < inp.length; i++) { const v = inp[i]; if (typeof v === 'string') walk(v, top); else if (Array.isArray(v) && typeof v[1] === 'string' && byId[v[1]]) walk(v[1], top); } }
  if (b.next) walk(b.next, top);
}
for (const t of targets) {
  for (const id in t.blocks) { const b = t.blocks[id]; if (b.topLevel) walk(id, id); }
}
const names = Object.keys(refs);
const hist = {};
for (const n of names) { const c = refs[n].size; hist[c] = (hist[c] || 0) + 1; }
console.log('variables referenced by N procedures:');
for (const k of Object.keys(hist).sort((a,b)=>a-b)) console.log('  ' + k + ' proc(s): ' + hist[k] + ' vars');
console.log('total vars referenced =', names.length);
const allVars = targets[0].variables ? Object.keys(targets[0].variables).length : 0;
console.log('declared variables in Interpreter =', allVars);

