block.text:
Now let me implement the spilling. I'll replace section 4 with a version that:
1. Ranks new variables by use count and keeps the top KEEP.
2. Creates the `Reg` list with one slot per spilled register.
3. Rewrites each block:
   - `data_variable` + spilled → mutate to `data_itemoflist('Reg', slot)`.
   - `data_setvariableto` + spilled → mutate to `data_replaceitemoflist('Reg', slot, ITEM=VALUE)`.
   - `data_changevariableby` + spilled → mutate to `data_replaceitemoflist` with ITEM = `operator_add(item(Reg,slot), oldValue)` (creating the add block + the item block).
4. Keep `tgt.variables` = only the kept ones.

Let me write the code:

```js
  // ---------- 4. rewrite ----------
  // §10: keep only a handful of Scratch variables.  Registers are ranked by how many blocks
  // touch them; the hottest KEEP stay variables and every other one moves into a slot of the
  // `Reg` list.  Slots are per web, so this cannot alias anything.
  const useCount = Object.create(null);
  for (const id in blocks) {
    const f = blocks[id].fields;
    if (!f || !f.VARIABLE) continue;
    const nv = assignAt[id] || assign[f.VARIABLE[1]];
    if (nv) useCount[nv] = (useCount[nv] || 0) + 1;
  }
  const KEEP = Math.max(0, Number(process.env.V5_KEEPVARS || 16));
  const ranked = Object.keys(newVars).sort((a, b) => (useCount[b] || 0) - (useCount[a] || 0));
  const slotOf = Object.create(null);
  let spilled = 0;
  for (let i = KEEP; i < ranked.length; i++) slotOf[ranked[i]] = spilled++;
  const REGLIST = 'Reg';
  const REGID = 'v5reglist';
  if (!o.dryRun && spilled) {
    tgt.lists = tgt.lists || {};
    tgt.lists[REGID] = [REGLIST, new Array(spilled).fill('')];
  }
  const numIn = (n) => [1, [7, String(n)]];
  let nextId = 0;
  const freshId = () => 'v5spill' + (nextId++);
  let rewrites = 0, spilledRefs = 0;
  for (const id in blocks) {
    const b = blocks[id];
    const f = b.fields;
    if (!f || !f.VARIABLE) continue;
    const nid = assignAt[id] || assign[f.VARIABLE[1]];
    if (!nid) continue;
    const slot = slotOf[nid];
    if (slot === undefined) {
      if (newVars[nid]) f.VARIABLE = [newVars[nid][0], nid];
      rewrites++;
      continue;
    }
    spilledRefs++;
    if (b.opcode === 'data_variable') {
      b.opcode = 'data_itemoflist';
      b.fields = { LIST: [REGLIST, REGID] };
      b.inputs = { INDEX: numIn(slot + 1) };
    } else if (b.opcode === 'data_setvariableto') {
      const val = b.inputs.VALUE;
      b.opcode = 'data_replaceitemoflist';
      b.fields = { LIST: [REGLIST, REGID] };
      b.inputs = { INDEX: numIn(slot + 1), ITEM: val };
    } else if (b.opcode === 'data_changevariableby') {
      const val = b.inputs.VALUE;
      const itemId = freshId(), addId = freshId();
