{"code": "const suites = [["vtest.json","vtruth.json"],["cases73.json","truth73.json"],["xtest.json","xtruth.json"],["ytest.json","ytruth.json"],["zsuite.json","ztruth.json"],["jst.json","jstruth.json"],["ft.json","ftruth.json"],["lctest.json","lctruth.json"],["dctest.json","dctruth.json"],["bigtest.json","bigtruth.json"],["ttest.json","ttruth.json"],["stest.json","struth.json"],["rtest.json","rtruth.json"],["etest.json","etruth.json"],["utest.json","utruth.json"],["nc.json","nctruth.json"],["btest.json","btruth.json"],["gtest.json","gtruth.json"],["ntest.json","ntruth.json"],["stest2.json","struth2.json"],["wtest.json","wtruth.json"]];
const cmds = ["node _work\\v5\\check.js _work\\v5\\rAZ.sb3 | Select-String 'OK'"];
for (const [c, t] of suites) cmds.push("node _work\\v5\\run5.cjs _work\\v5\\rAZ.sb3 _work\\v5\\" + c + " --truth _work\\v5\\" + t + " --max 8000 2>$null | Select-Object -First 1");
const r = await tools.pwsh({ command: cmds.join("; "), description: "Full sweep after the revert", workdir: "D:\\编程\\scratch\\ai\\minipython", timeoutMs: 600000 });
const lines = r.stdout.text.split(String.fromCharCode(10)).map(l => l.trim()).filter(l => l.length > 0);
let total = 0, bad = 0, idx = 0;
for (const l of lines) {
  const m = l.match(/PASS (\d+)\s+FAIL (\d+)/);
  if (m) { total += Number(m[1]) + Number(m[2]); bad += Number(m[2]); if (Number(m[2])) console.log("FAIL " + (suites[idx] ? suites[idx][0] : "?") + ": " + l); idx++; }
  else console.log("structure: " + l);
}
console.log("TOTAL cases:", total, "failures:", bad);
", "description": "Full sweep after the revert"}

